def skinny_native_entry(
    arch: str, M: int, N: int, K: int, layout: str, ld_odd: bool
) -> Optional[tuple]:
    """The native table entry of a shape on ``arch`` (None outside it: no
    table for the arch, min(M, N) > 1023, or the RCR layout)."""
    table = SKINNY_NATIVE_TABLE.get(arch)
    if table is None:
        return None
    s, g = min(int(M), int(N)), max(int(M), int(N))
    bs = int(math.floor(math.log2(max(1, s))))
    if bs > 9:
        return None
    bg = min(15, max(7, int(math.floor(math.log2(max(1, g))))))
    bk = min(15, max(6, int(math.floor(math.log2(max(1, int(K)))))))
    return table.get((str(layout).upper(), int(M <= N), int(bool(ld_odd)), bs, bg, bk))
